  // texture is unusable); manual override reads whatever the designer typed.
  const bond = autoBond ? (suggestedBond ?? HUESKER_BOND_DEFAULT) : hueskerNum(v.hueskerBondCoat);
  const target = hueskerNum(v.hueskerOverallTarget);
